// A text-based invoice from user testing on 2026-11-09 (A4 generated by pdf-lib, headers Item / Qty
// / Unit price / Amount, four item rows, each with a very light thin horizontal line underneath and
// no vertical lines; bottom right contains Subtotal / VAT 20% / Total due). Lines recognized by
// PP-OCRv6 rendered as an image with 2000 max edge using iOS pdf.toImages (for D-506 tests). The
// thin horizontal lines are too faint for line detection.

import type { OcrBox } from '../types';

const line = (text: string, x: number, y: number, width: number, height: number): OcrBox => ({
  text,
  x,
  y,
  width,
  height,
});

